package pkg004

// Func004_04_00 is a deterministically generated function
// for the repomap perf fixture; it references Func005_05_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func004_04_00(a, b int) int {
	if a > b {
		return Func005_05_00(a, b) + a
	}
	return Func005_05_00(b, a) - b
}

